    private val SIGNATURES_BY_PAYLOAD_SIZE: Map<Int, List<List<ByteArray>>> = mapOf(
        PAYLOAD_SIZE_DEFAULT to SIGNATURES_PAYLOAD_SIZE_DEFAULT,
        maxTransactionV1PayloadSize(1) to SIGNATURES_MAX_TRANSACTION_V1_1_SIGNATURE,
        maxTransactionV1PayloadSize(3) to SIGNATURES_MAX_TRANSACTION_V1_3_SIGNATURES,
    )

    private val RESOLVED_DERIVATION_PATHS: List<List<Uri>> =
        (0 until MAX_SIGNING_REQUESTS).map { i ->
            (0 until SIGNATURES_INCREMENT).map { j ->
                Uri.parse(
                    "${WalletContractV1.BIP32_URI_SCHEME}:" +
                            "/${WalletContractV1.BIP32_URI_MASTER_KEY_INDICATOR}/44'/501'/" +
                            "${i * SIGNATURES_INCREMENT + j}" +
                            WalletContractV1.BIP_URI_HARDENED_INDEX_IDENTIFIER
                )!!
            }
        }

    /**
     * The [SigningResponse]s expected when [signingRequests] payloads of [payloadSize] bytes are
     * each signed [signaturesPerRequest] times.
     */
    fun expectedSignatures(
        payloadSize: Int,
        signingRequests: Int,
        signaturesPerRequest: Int
    ): ArrayList<SigningResponse> {
        require(signingRequests <= MAX_SIGNING_REQUESTS) {
            "No dataset for $signingRequests signing requests (max $MAX_SIGNING_REQUESTS)"
        }
        require(signaturesPerRequest <= SIGNATURES_INCREMENT) {
            "No dataset for $signaturesPerRequest signatures per request (max $SIGNATURES_INCREMENT)"
        }
        val signatures = requireNotNull(SIGNATURES_BY_PAYLOAD_SIZE[payloadSize]) {
            "No signature dataset for a $payloadSize byte payload; one must be generated to cover " +
                    "this implementation"
        }

        return ArrayList((0 until signingRequests).map { i ->
            SigningResponse(
                signatures[i].take(signaturesPerRequest),
                RESOLVED_DERIVATION_PATHS[i].take(signaturesPerRequest)
            )
        })
    }
